const state={data:null,costs:null,view:'overview',provider:'',month:'',search:'',selectedProduct:'',mapQuery:'',mapPage:0,tracePage:0,costTab:'base',costQuery:'',costPage:0,threshold:10,overrides:JSON.parse(localStorage.getItem('avanti-mapping')||'{}')};
const $=s=>document.querySelector(s);const content=$('#content');
const money=n=>n==null?'—':new Intl.NumberFormat('es-PE',{style:'currency',currency:'PEN',maximumFractionDigits:2}).format(n);
const dateFmt=s=>s?new Intl.DateTimeFormat('es-PE',{day:'2-digit',month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(s+'T00:00:00Z')):'—';
const esc=s=>String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const effProduct=r=>state.overrides[r.description]||r.product;
const unique=a=>[...new Set(a)];
const rows=()=>state.data.rows.filter(r=>(!state.provider||r.provider===state.provider)&&(!state.month||r.date.startsWith(state.month)));
const productRows=name=>rows().filter(r=>effProduct(r)===name);
const products=()=>{const counts=new Map();rows().forEach(r=>counts.set(effProduct(r),(counts.get(effProduct(r))||0)+1));return [...counts].sort((a,b)=>b[1]-a[1]);};
const lastBy=(arr,key)=>Object.values(arr.reduce((o,r)=>{const k=r[key];if(!o[k]||r.date>o[k].date)o[k]=r;return o},{}));
const daysSince=s=>Math.max(0,Math.round((new Date('2026-10-19T00:00:00Z')-new Date(s+'T00:00:00Z'))/86400000));

function alertData(scope=rows()){
  const priced=scope.filter(r=>!r.bonus&&r.price!=null).sort((a,b)=>a.date.localeCompare(b.date));
  const hist=new Map(),rises=[],anomalies=priced.filter(r=>r.price<=.1);
  priced.filter(r=>r.price>.1).forEach(r=>{const k=effProduct(r)+'|'+r.provider+'|'+r.comparisonKey,p=hist.get(k);if(p){const pct=(r.price-p.price)/p.price*100;if(pct>state.threshold)rises.push({...r,pct,prev:p.price})}hist.set(k,r)});
  const deps=[];const productProviders=new Map();scope.forEach(r=>{const p=effProduct(r);if(!productProviders.has(p))productProviders.set(p,new Set());productProviders.get(p).add(r.provider)});productProviders.forEach((v,k)=>{if(v.size===1)deps.push({product:k,provider:[...v][0]})});
  return {rises:rises.sort((a,b)=>b.pct-a.pct),deps,anomalies};
}
function comparativeGroups(scope=rows()){
  const groups=new Map();scope.filter(r=>!r.bonus&&r.price!=null&&r.price>.1).forEach(r=>{const k=effProduct(r)+'|'+r.comparisonKey;if(!groups.has(k))groups.set(k,[]);groups.get(k).push(r)});
  return [...groups].map(([key,rs])=>{const latest=lastBy(rs,'provider').sort((a,b)=>a.price-b.price);const prov=unique(rs.map(r=>r.provider));const comparable=prov.length>1&&!key.endsWith('|?');const cheapest=latest[0];let saving=0;if(comparable)rs.forEach(r=>saving+=Math.max(0,(r.price-cheapest.price)*(r.qty||0)));return {key,product:effProduct(rs[0]),comparisonKey:rs[0].comparisonKey,latest,prov,comparable,saving,rows:rs}}).sort((a,b)=>b.saving-a.saving);
}

function render(){document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view));({overview:renderOverview,product:renderProduct,compare:renderCompare,costs:renderCosts,mapping:renderMapping,trace:renderTrace}[state.view])();}
function renderOverview(){const scope=rows(),nonBonus=scope.filter(r=>!r.bonus),bonus=scope.filter(r=>r.bonus),inv=unique(scope.map(r=>r.provider+'|'+r.invoice+'|'+r.file)).length,prod=unique(scope.map(effProduct)).length,alerts=alertData(scope),providerCounts=Object.entries(scope.reduce((o,r)=>(o[r.provider]=(o[r.provider]||0)+1,o),{})).sort((a,b)=>b[1]-a[1]),max=providerCounts[0]?.[1]||1;content.innerHTML=`<div class="view"><section class="hero"><div><p class="eyebrow" style="color:#b8dd72">DECISIONES DE COMPRA, CON RASTRO</p><h2>¿A quién conviene comprarle hoy?</h2><p>Busca un medicamento para ver precios, evolución y última compra. Las comparaciones dudosas se detienen antes de producir un ahorro ficticio.</p></div><div class="hero-badge"><strong>${state.data.meta.months.length}</strong><span>MESES CON DATOS</span></div></section><div class="quality-alert">⚑ <span><b>Control de calidad:</b> la base contiene ${state.data.meta.descriptionCount.toLocaleString('es-PE')} descripciones únicas; el documento de encargo declara ${state.data.meta.sourceDescriptionCountClaim.toLocaleString('es-PE')}. Se usa el dato observado.</span></div><section class="kpis">${kpi('▤',scope.length.toLocaleString('es-PE'),'Líneas de factura','Dato crudo')}${kpi('⌁',inv.toLocaleString('es-PE'),'Facturas rastreables','archivo + número')}${kpi('◈',prod.toLocaleString('es-PE'),'Productos propuestos',state.data.meta.descriptionCount-prod+' variantes agrupadas')}${kpi('＋',bonus.length.toLocaleString('es-PE'),'Bonificaciones','separadas del precio')}</section><div class="grid-2"><article class="card"><div class="card-header"><div><h3>Volumen de líneas por distribuidor</h3><p>Participación en el período filtrado</p></div><span class="pill">${unique(scope.map(r=>r.provider)).length} proveedores</span></div>${providerCounts.slice(0,8).map(([p,n])=>`<div class="bar-row"><span>${esc(p)}</span><div class="bar-track"><div class="bar-fill" style="width:${n/max*100}%"></div></div><strong>${n}</strong></div>`).join('')}</article><article class="card"><div class="card-header"><div><h3>Atención de compras</h3><p>Lo que merece una mirada primero</p></div><span class="pill">umbral +${state.threshold}%</span></div><div class="alert-list">${alerts.rises.slice(0,3).map(r=>alertItem('red',effProduct(r),`${r.provider} · ${money(r.prev)} → ${money(r.price)}`,'+'+r.pct.toFixed(1)+'%')).join('')}${alerts.anomalies.length?alertItem('amber',alerts.anomalies.length+' precios ≤ S/ 0.10','Excluidos de alertas y comparativos','Validar dato'):''}${alertItem('amber',alerts.deps.length+' productos con proveedor único','Riesgo de dependencia en el período','Revisar')}${alertItem('blue',bonus.length+' líneas bonificadas','Fuera de promedios y comparativos','Separadas')}</div></article></div></div>`}
function kpi(icon,value,label,note){return `<article class="kpi"><div class="kpi-top"><div class="kpi-icon">${icon}</div><span class="kpi-delta">${esc(note)}</span></div><strong>${value}</strong><span>${label}</span></article>`}
function alertItem(color,title,sub,val){return `<div class="alert-item"><i class="alert-dot ${color}"></i><div><b>${esc(title)}</b><span>${esc(sub)}</span></div><em>${esc(val)}</em></div>`}

function chooseDefaultProduct(){if(state.selectedProduct&&productRows(state.selectedProduct).length)return;state.selectedProduct=products()[0]?.[0]||''}
function renderProduct(){chooseDefaultProduct();const rs=productRows(state.selectedProduct).sort((a,b)=>a.date.localeCompare(b.date)),priced=rs.filter(r=>!r.bonus&&r.price!=null),latest=lastBy(priced,'provider').sort((a,b)=>a.price-b.price),bonus=rs.filter(r=>r.bonus),best=latest[0];content.innerHTML=`<div class="view"><div class="section-head"><div class="product-title"><div class="product-glyph">✣</div><div><h2>${esc(state.selectedProduct||'Selecciona un producto')}</h2><p>${unique(rs.map(r=>r.description)).length} descripciones · ${unique(rs.map(r=>r.provider)).length} proveedores · ${rs.length} compras</p></div></div><button class="btn secondary" onclick="state.view='mapping';state.mapQuery=state.selectedProduct;render()">Revisar equivalencias</button></div>${rs.length?`<div class="assumption">ⓘ El “precio observado” puede provenir de columnas distintas según el proveedor. Cada tarjeta y cada fila indica su base; una cifra calculada nunca se presenta como impresa.</div><section class="provider-grid">${latest.map(r=>`<article class="provider-card ${r===best?'best':''}"><small>${esc(r.provider)} ${r===best?'<span class="tag">menor observado</span>':''}</small><strong>${money(r.price)}</strong><span class="basis">${esc(r.priceBasis)}${r.calculated?' · cálculo':''}</span><footer><span>${dateFmt(r.date)}</span><span>hace ${daysSince(r.date)} días</span></footer></article>`).join('')}</section><div class="grid-2"><article class="card"><div class="card-header"><div><h3>Evolución de precio</h3><p>Una línea por proveedor · solo líneas no bonificadas</p></div><span class="pill">${priced.length} observaciones</span></div>${renderChart(priced)}</article><article class="card"><div class="card-header"><div><h3>Bonificaciones</h3><p>Unidades recibidas sin contaminar el precio</p></div><span class="pill">${bonus.length} líneas</span></div>${bonus.length?bonus.slice(-7).reverse().map(r=>alertItem('blue',r.provider,`${r.qty??'—'} ${r.um} · ${dateFmt(r.date)}`,r.invoice||'PDF')).join(''):'<div class="empty"><b>Sin bonificaciones</b>No hay líneas marcadas para este producto.</div>'}</article></div><article class="card" style="margin-top:15px"><div class="card-header"><div><h3>Compras y documentos</h3><p>Cada valor conserva factura y archivo de origen</p></div><span class="pill">${rs.length} líneas</span></div>${rowsTable(rs.slice().reverse(),18)}</article>`:'<div class="empty"><b>No hay producto seleccionado</b>Usa el buscador superior para abrir una ficha.</div>'}</div>`}
function renderChart(rs){if(!rs.length)return '<div class="empty"><b>Sin precios utilizables</b>Las líneas pueden ser bonificaciones o no traer un precio interpretable.</div>';const W=760,H=220,pad=36,dates=unique(rs.map(r=>r.date)).sort(),minD=new Date(dates[0]),maxD=new Date(dates.at(-1)),vals=rs.map(r=>r.price),min=Math.min(...vals),max=Math.max(...vals),span=max-min||1,colors=['#14534b','#c6524c','#477d91','#d7932d','#6f5685','#3f8f65','#9b5f3f','#56726e'];const providers=unique(rs.map(r=>r.provider));const x=d=>pad+((new Date(d)-minD)/(maxD-minD||1))*(W-pad*2),y=v=>H-pad-(v-min)/span*(H-pad*2);let svg=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Evolución del precio"><line x1="${pad}" y1="${H-pad}" x2="${W-pad}" y2="${H-pad}" stroke="#dfe5de"/><text x="${pad}" y="${H-8}" font-size="10" fill="#70807c">${dateFmt(dates[0])}</text><text x="${W-pad}" text-anchor="end" y="${H-8}" font-size="10" fill="#70807c">${dateFmt(dates.at(-1))}</text><text x="3" y="${pad}" font-size="10" fill="#70807c">${money(max)}</text><text x="3" y="${H-pad}" font-size="10" fill="#70807c">${money(min)}</text>`;providers.forEach((p,i)=>{const pts=rs.filter(r=>r.provider===p).sort((a,b)=>a.date.localeCompare(b.date));svg+=`<polyline points="${pts.map(r=>`${x(r.date)},${y(r.price)}`).join(' ')}" fill="none" stroke="${colors[i%colors.length]}" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>`;pts.forEach(r=>svg+=`<circle cx="${x(r.date)}" cy="${y(r.price)}" r="3.5" fill="white" stroke="${colors[i%colors.length]}" stroke-width="2"><title>${p} · ${dateFmt(r.date)} · ${money(r.price)}</title></circle>`)});svg+='</svg>';return `<div class="chart-wrap">${svg}</div><div class="legend">${providers.map((p,i)=>`<span><i style="background:${colors[i%colors.length]}"></i>${esc(p)}</span>`).join('')}</div>`}

function renderCompare(){const groups=comparativeGroups(),good=groups.filter(g=>g.comparable&&g.prov.length>1),blocked=groups.filter(g=>g.prov.length>1&&!g.comparable);content.innerHTML=`<div class="view"><div class="section-head"><div><p class="eyebrow">COMPARACIÓN PRUDENTE</p><h2>Oportunidades entre distribuidores</h2><p>Solo misma equivalencia propuesta, unidad normalizada y presentación explícita.</p></div><span class="pill">${good.length} comparables · ${blocked.length} bloqueados</span></div><div class="assumption">⚑ El ahorro es una estimación: aplica el menor precio observado del grupo a las cantidades históricas. No corrige IGV ni unidades por envase ausentes.</div><div class="compare-list">${good.slice(0,60).map(g=>`<article class="compare-card" onclick="state.selectedProduct=${JSON.stringify(g.product)};state.view='product';render()"><h3>${esc(g.product)}</h3><span class="muted">Presentación: ${esc(g.comparisonKey.replace('|',' · x'))}</span><div class="compare-suppliers">${g.latest.map((r,i)=>`<div class="supplier-chip ${i===0?'best':''}">${esc(r.provider)}<br><b>${money(r.price)}</b></div>`).join('')}</div><div class="compare-foot"><span>${g.rows.length} compras observadas</span><strong>Ahorro estimado ${money(g.saving)}</strong></div></article>`).join('')||'<div class="empty"><b>Sin comparaciones seguras</b>Ajusta filtros o revisa equivalencias.</div>'}</div>${blocked.length?`<article class="card" style="margin-top:16px"><div class="card-header"><div><h3>No comparables por presentación ausente</h3><p>No se fuerza una conversión cuando el envase no está explícito.</p></div><span class="pill">${blocked.length}</span></div>${blocked.slice(0,10).map(g=>alertItem('amber',g.product,g.prov.join(' · '),'No comparable')).join('')}</article>`:''}</div>`}

function renderMapping(){const q=state.mapQuery.toLowerCase(),all=state.data.mappings.filter(m=>!q||m.description.toLowerCase().includes(q)||((state.overrides[m.description]||m.product).toLowerCase().includes(q))),page=all.slice(state.mapPage*50,state.mapPage*50+50);content.innerHTML=`<div class="view"><div class="section-head"><div><p class="eyebrow">TABLA EDITABLE</p><h2>Equivalencias de producto</h2><p>Descripción del proveedor → producto normalizado propuesto.</p></div><div class="mapping-toolbar"><input id="mapSearch" value="${esc(state.mapQuery)}" placeholder="Filtrar equivalencias…"><button class="btn secondary" id="exportMap">Exportar CSV</button></div></div><div class="assumption">ⓘ Las ${state.data.meta.productCount.toLocaleString('es-PE')} agrupaciones iniciales son automáticas y conservadoras. Las correcciones se guardan solo en este navegador hasta exportarlas.</div><div class="table-wrap"><table class="data-table"><thead><tr><th>Descripción del proveedor</th><th>Producto normalizado editable</th><th>Estado</th></tr></thead><tbody>${page.map(m=>`<tr class="${state.overrides[m.description]?'edited':''}"><td>${esc(m.description)}</td><td><input class="mapping-input" data-desc="${esc(m.description)}" value="${esc(state.overrides[m.description]||m.product)}"></td><td>${state.overrides[m.description]?'<span class="tag">editado</span>':'<span class="muted">propuesto</span>'}</td></tr>`).join('')}</tbody></table></div>${pager(all.length,state.mapPage,'map')}</div>`;$('#mapSearch').oninput=e=>{state.mapQuery=e.target.value;state.mapPage=0;renderMapping()};document.querySelectorAll('.mapping-input').forEach(i=>i.onchange=e=>{const d=e.target.dataset.desc,v=e.target.value.trim();if(v)state.overrides[d]=v;else delete state.overrides[d];localStorage.setItem('avanti-mapping',JSON.stringify(state.overrides));renderMapping()});$('#exportMap').onclick=exportMapping}
function exportMapping(){const lines=[['descripcion_proveedor','producto_normalizado','estado'],...state.data.mappings.map(m=>[m.description,state.overrides[m.description]||m.product,state.overrides[m.description]?'editado':'propuesto'])];const csv=lines.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv'}));a.download='equivalencias_avanti.csv';a.click();URL.revokeObjectURL(a.href)}

function renderTrace(){let scope=rows();if(state.search){const q=state.search.toLowerCase();scope=scope.filter(r=>[r.description,effProduct(r),r.code,r.invoice,r.file].some(v=>String(v).toLowerCase().includes(q)))}const page=scope.slice(state.tracePage*75,state.tracePage*75+75);content.innerHTML=`<div class="view"><div class="section-head"><div><p class="eyebrow">AUDITORÍA</p><h2>Trazabilidad de documentos</h2><p>Cada cifra vuelve a su factura, archivo y línea original.</p></div><span class="pill">${scope.length.toLocaleString('es-PE')} líneas</span></div>${rowsTable(page,75,true)}${pager(scope.length,state.tracePage,'trace')}</div>`}

const costMoney=n=>n==null?'—':new Intl.NumberFormat('es-PE',{style:'currency',currency:'PEN',minimumFractionDigits:4,maximumFractionDigits:4}).format(n);
function costTabs(){return `<div class="cost-tabs">${[['base','Base maestra'],['compare','Comparativo'],['presentations','Presentaciones distintas'],['detail','Detalle del cálculo']].map(([id,label])=>`<button class="${state.costTab===id?'active':''}" data-cost-tab="${id}">${label}</button>`).join('')}</div>`}
function filteredCosts(list,fields){const q=state.costQuery.trim().toLowerCase();return list.filter(r=>(!state.provider||r.provider===state.provider)&&(!q||fields.some(f=>String(r[f]??'').toLowerCase().includes(q))))}
function costPager(total,size){const pages=Math.ceil(total/size);return `<div class="pagination"><span>${total.toLocaleString('es-PE')} registros · página ${state.costPage+1} de ${Math.max(1,pages)}</span><div><button onclick="state.costPage=Math.max(0,state.costPage-1);renderCosts()" ${state.costPage===0?'disabled':''}>←</button> <button onclick="state.costPage=Math.min(${Math.max(0,pages-1)},state.costPage+1);renderCosts()" ${state.costPage>=pages-1?'disabled':''}>→</button></div></div>`}
function exportCostsExcel(){
  if(!window.XLSX){alert('No se pudo cargar el generador de Excel. Recarga la página e inténtalo otra vez.');return}
  const d=state.costs,m=d.meta,wb=XLSX.utils.book_new();
  wb.Props={Title:'BD madre de costos',Subject:'Costos de compra por producto y proveedor',Author:'Avanti Pharma Group S.A.C.',Company:'Avanti Pharma Group S.A.C.'};
  const addSheet=(name,rows,widths,formats=[])=>{const ws=XLSX.utils.aoa_to_sheet(rows);ws['!cols']=widths.map(w=>({wch:w}));if(rows.length>1)ws['!autofilter']={ref:XLSX.utils.encode_range({s:{r:0,c:0},e:{r:rows.length-1,c:rows[0].length-1}})};formats.forEach(([col,fmt])=>{for(let row=1;row<rows.length;row++){const cell=ws[XLSX.utils.encode_cell({r:row,c:col})];if(cell&&cell.t==='n')cell.z=fmt}});XLSX.utils.book_append_sheet(wb,ws,name)};
  const control=[['BD madre de costos'],['Archivo fuente',m.source],['Fecha de exportación',new Intl.DateTimeFormat('es-PE',{dateStyle:'medium',timeStyle:'short'}).format(new Date())],['Filas base maestra',m.baseRows],['Productos',m.products],['Códigos GTIN',m.gtinCount],['Comparaciones',m.comparisons],['Presentaciones distintas',m.differentPresentations],['Filas de detalle',m.detailRows],[],['Criterio','Los costos representan costo final por tableta o unidad, con IGV.'],['Compra observada','Costo calculado desde una compra del mes.'],['Arrastrado','Último costo conocido cuando no hubo compra en el mes.'],['Sin dato','No existe un costo anterior disponible.']];
  const controlSheet=XLSX.utils.aoa_to_sheet(control);controlSheet['!cols']=[{wch:24},{wch:82}];XLSX.utils.book_append_sheet(wb,controlSheet,'Control');
  const baseHeader=['N°','Código GTIN','Producto','Proveedor',...m.months.flatMap(month=>[`${month} - costo final`,`${month} - origen`]),'Cantidad de proveedores','Unidades por caja','Unidades compradas','Meses con compra'];
  const baseRows=d.base.map(r=>[r.n,String(r.gtin||''),r.product,r.provider,...r.costs.flatMap(c=>[c.value,c.value==null?'Sin dato':c.carried?'Arrastrado':'Compra observada']),r.providerCount,r.unitsPerBox,r.unitsPurchased,r.monthsPurchased]);
  addSheet('Base maestra',[baseHeader,...baseRows],[7,18,42,28,...m.months.flatMap(()=>[16,18]),20,16,20,17],m.months.map((_,i)=>[4+i*2,'"S/ "0.0000']));
  const compareHeader=['N°','Código GTIN','Producto','Unidades por caja','Cantidad de proveedores','Proveedor más barato','Costo más barato','Proveedor más caro','Costo más caro','Diferencia','Diferencia %','Unidades compradas','Ahorro estimado'];
  const compareRows=d.comparisons.map(r=>[r.n,String(r.gtin||''),r.product,r.unitsPerBox,r.providerCount,r.cheapest,r.cheapestCost,r.mostExpensive,r.mostExpensiveCost,r.difference,r.differencePct==null?null:r.differencePct/100,r.unitsPurchased,r.estimatedSaving]);
  addSheet('Comparativo',[compareHeader,...compareRows],[7,18,42,17,20,28,16,28,16,16,14,19,18],[[6,'"S/ "0.0000'],[8,'"S/ "0.0000'],[9,'"S/ "0.0000'],[10,'0.0%'],[12,'"S/ "#,##0.00']]);
  const presentationHeader=['N°','Código GTIN','Producto','Detalle de presentación'];
  const presentationRows=d.presentations.map(r=>[r.n,String(r.gtin||''),r.product,r.detail]);
  addSheet('Presentaciones',[presentationHeader,...presentationRows],[7,18,46,72]);
  const detailHeader=['N°','Código GTIN','Producto en factura','Proveedor','Mes','N° factura','Archivo','Cajas','Unidades por caja','Unidades','Importe de factura','Costo sin IGV','IGV','Costo final','Origen del importe','Origen de unidades por caja'];
  const detailRows=d.detail.map(r=>[r.n,String(r.gtin||''),r.description,r.provider,r.month,r.invoice,r.file,r.boxes,r.unitsPerBox,r.units,r.invoiceAmount,r.costWithoutTax,r.tax,r.finalCost,r.amountSource,r.unitsSource]);
  addSheet('Detalle del cálculo',[detailHeader,...detailRows],[7,18,48,28,14,18,38,11,18,14,19,17,10,16,30,44],[[10,'"S/ "#,##0.00'],[11,'"S/ "0.0000'],[13,'"S/ "0.0000']]);
  XLSX.writeFile(wb,`BD_madre_costos_Avanti_${new Date().toISOString().slice(0,10)}.xlsx`,{compression:true});
}
function renderCosts(){const d=state.costs,m=d.meta;let body='';if(state.costTab==='base'){const all=filteredCosts(d.base,['gtin','product','provider']),size=40,page=all.slice(state.costPage*size,state.costPage*size+size);body=`<div class="table-wrap cost-table"><table class="data-table"><thead><tr><th>N°</th><th>Código GTIN</th><th>Producto</th><th>Proveedor</th>${m.months.map(x=>`<th>${x}</th>`).join('')}<th>¿Cuántos proveedores?</th><th>Unid. por caja</th><th>Unidades compradas</th><th>Meses con compra</th></tr></thead><tbody>${page.map(r=>`<tr><td>${r.n}</td><td class="mono">${esc(r.gtin||'Sin GTIN')}</td><td><b>${esc(r.product)}</b></td><td>${esc(r.provider)}</td>${r.costs.map(c=>`<td class="cost-cell ${c.carried?'carried':'actual'}" title="${c.carried?'Arrastrado del mes anterior':'Compra observada en el mes'}">${costMoney(c.value)}</td>`).join('')}<td>${r.providerCount}</td><td>${r.unitsPerBox??'—'}</td><td>${(r.unitsPurchased??0).toLocaleString('es-PE')}</td><td>${r.monthsPurchased}</td></tr>`).join('')}</tbody></table></div>${costPager(all.length,size)}`}
  else if(state.costTab==='compare'){const all=filteredCosts(d.comparisons,['gtin','product','cheapest','mostExpensive']),size=40,page=all.slice(state.costPage*size,state.costPage*size+size);body=`<div class="table-wrap cost-table"><table class="data-table"><thead><tr><th>N°</th><th>Código GTIN</th><th>Producto</th><th>Unid. por caja</th><th>Proveedores</th><th>Más barato</th><th>Su costo</th><th>Más caro</th><th>Su costo</th><th>Diferencia</th><th>Diferencia %</th><th>Unidades compradas</th><th>Ahorro si todo fuera al más barato</th></tr></thead><tbody>${page.map(r=>`<tr><td>${r.n}</td><td class="mono">${esc(r.gtin)}</td><td><b>${esc(r.product)}</b></td><td>${r.unitsPerBox??'—'}</td><td>${r.providerCount}</td><td><span class="tag">${esc(r.cheapest)}</span></td><td><b>${costMoney(r.cheapestCost)}</b></td><td>${esc(r.mostExpensive)}</td><td>${costMoney(r.mostExpensiveCost)}</td><td>${costMoney(r.difference)}</td><td>${r.differencePct==null?'—':r.differencePct.toFixed(1)+'%'}</td><td>${(r.unitsPurchased??0).toLocaleString('es-PE')}</td><td><b>${money(r.estimatedSaving)}</b></td></tr>`).join('')}</tbody></table></div>${costPager(all.length,size)}`}
  else if(state.costTab==='presentations'){const all=filteredCosts(d.presentations,['gtin','product','detail']);body=`<div class="presentation-grid">${all.map(r=>`<article class="presentation-card"><span class="mono">${esc(r.gtin||'Sin GTIN')}</span><h3>${esc(r.product)}</h3><p>${esc(r.detail)}</p><span class="tag bonus">No comparar directo</span></article>`).join('')||'<div class="empty"><b>Sin resultados</b>No hay presentaciones distintas para este filtro.</div>'}</div>`}
  else {const all=filteredCosts(d.detail,['gtin','description','provider','invoice','file']),size=50,page=all.slice(state.costPage*size,state.costPage*size+size);body=`<div class="table-wrap cost-table"><table class="data-table"><thead><tr><th>N°</th><th>GTIN</th><th>Producto en factura</th><th>Proveedor</th><th>Mes</th><th>N° factura</th><th>Archivo</th><th>Cajas</th><th>Unid. por caja</th><th>Unidades</th><th>Importe factura</th><th>Costo sin IGV</th><th>IGV</th><th>Costo final</th><th>Origen del importe</th><th>Origen de unidades/caja</th></tr></thead><tbody>${page.map(r=>`<tr><td>${r.n}</td><td class="mono">${esc(r.gtin||'—')}</td><td><b>${esc(r.description)}</b></td><td>${esc(r.provider)}</td><td>${esc(r.month)}</td><td class="mono">${esc(r.invoice)}</td><td>${esc(r.file)}</td><td>${r.boxes??'—'}</td><td>${r.unitsPerBox??'—'}</td><td>${r.units??'—'}</td><td>${money(r.invoiceAmount)}</td><td>${costMoney(r.costWithoutTax)}</td><td>${esc(r.tax)}</td><td><b>${costMoney(r.finalCost)}</b></td><td>${esc(r.amountSource)}</td><td>${esc(r.unitsSource)}</td></tr>`).join('')}</tbody></table></div>${costPager(all.length,size)}`}
  content.innerHTML=`<div class="view"><div class="section-head"><div><p class="eyebrow">COSTO POR TABLETA O UNIDAD, CON IGV</p><h2>BD madre de costos</h2><p>Estructura de la plantilla: GTIN, producto, proveedor y costo promedio mensual.</p></div><span class="pill">Mayo–diciembre 2026</span></div><section class="kpis cost-kpis">${kpi('GT',m.gtinCount.toLocaleString('es-PE'),'Códigos GTIN','identificados')}${kpi('▦',m.baseRows.toLocaleString('es-PE'),'Filas producto–proveedor','base maestra')}${kpi('⇄',m.comparisons.toLocaleString('es-PE'),'Productos comparables','más de un proveedor')}${kpi('!',m.differentPresentations.toLocaleString('es-PE'),'Presentaciones distintas','sin comparación directa')}</section><div class="cost-note"><b>Criterio de la plantilla.</b> Los costos son por tableta o unidad y con IGV. Las celdas grises arrastran el último costo cuando no hubo compra; las verdes corresponden a compras observadas en ese mes.</div><div class="cost-toolbar">${costTabs()}<input id="costSearch" value="${esc(state.costQuery)}" placeholder="Buscar GTIN, producto, proveedor o factura…"><button class="btn secondary" id="exportCosts" title="Descarga las cuatro tablas completas">Exportar Excel</button></div>${body}</div>`;document.querySelectorAll('[data-cost-tab]').forEach(b=>b.onclick=()=>{state.costTab=b.dataset.costTab;state.costPage=0;renderCosts()});$('#costSearch').oninput=e=>{state.costQuery=e.target.value;state.costPage=0;renderCosts()};$('#exportCosts').onclick=exportCostsExcel}
function rowsTable(rs,limit,showRaw=false){return `<div class="table-wrap"><table class="data-table"><thead><tr><th>Fecha</th><th>Proveedor</th><th>Descripción</th><th>Cant.</th><th>Precio observado</th><th>Base</th><th>Factura / archivo</th>${showRaw?'<th>Línea original</th>':''}</tr></thead><tbody>${rs.slice(0,limit).map(r=>`<tr><td>${dateFmt(r.date)}</td><td><b>${esc(r.provider)}</b></td><td>${esc(r.description)}${r.bonus?' <span class="tag bonus">bonificación</span>':''}</td><td>${r.qty??'—'} ${esc(r.um)}</td><td><b>${r.bonus?'Separada':money(r.price)}</b>${r.calculated?' <span class="tag calc">calculado</span>':''}</td><td>${esc(r.priceBasis)}</td><td><span class="mono">${esc(r.invoice||'s/n')}</span><br><span class="muted">${esc(r.file)}</span></td>${showRaw?`<td class="mono muted">${esc(r.raw)}</td>`:''}</tr>`).join('')}</tbody></table></div>`}
function pager(total,page,type){const pages=Math.ceil(total/(type==='trace'?75:50));return `<div class="pagination"><span>${total.toLocaleString('es-PE')} registros · página ${page+1} de ${Math.max(1,pages)}</span><div><button onclick="state.${type}Page=Math.max(0,state.${type}Page-1);render()" ${page===0?'disabled':''}>←</button> <button onclick="state.${type}Page=Math.min(${Math.max(0,pages-1)},state.${type}Page+1);render()" ${page>=pages-1?'disabled':''}>→</button></div></div>`}

function initEvents(){document.querySelectorAll('.nav-item').forEach(b=>b.onclick=()=>{state.view=b.dataset.view;render()});$('#providerFilter').onchange=e=>{state.provider=e.target.value;state.selectedProduct='';render()};$('#monthFilter').onchange=e=>{state.month=e.target.value;state.selectedProduct='';render()};$('#clearFilters').onclick=()=>{state.provider=state.month=state.search='';$('#providerFilter').value=$('#monthFilter').value=$('#globalSearch').value='';render()};$('#helpBtn').onclick=()=>$('#criteriaDialog').showModal();$('.dialog-close').onclick=()=>$('#criteriaDialog').close();const input=$('#globalSearch'),box=$('#searchResults');input.oninput=e=>{state.search=e.target.value.trim();if(!state.search){box.classList.add('hidden');return}const q=state.search.toLowerCase(),matches=products().filter(([p])=>p.toLowerCase().includes(q)).slice(0,10);box.innerHTML=matches.map(([p,n])=>`<button class="search-result" data-product="${esc(p)}"><b>${esc(p)}</b><small>${n} líneas · ${unique(productRows(p).map(r=>r.provider)).length} proveedores</small></button>`).join('')||'<div class="empty" style="padding:20px">Sin coincidencias</div>';box.classList.remove('hidden');box.querySelectorAll('button').forEach(b=>b.onclick=()=>{state.selectedProduct=b.dataset.product;state.view='product';input.value=b.dataset.product;box.classList.add('hidden');render()})};document.addEventListener('click',e=>{if(!e.target.closest('.search'))box.classList.add('hidden')});document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();input.focus()}})}

Promise.all([fetch('data.json').then(r=>r.json()),fetch('costs.json').then(r=>r.json())]).then(([data,costs])=>{state.data=data;state.costs=costs;data.meta.providers.forEach(p=>$('#providerFilter').insertAdjacentHTML('beforeend',`<option>${esc(p)}</option>`));data.meta.months.forEach(m=>$('#monthFilter').insertAdjacentHTML('beforeend',`<option value="${m}">${new Intl.DateTimeFormat('es-PE',{month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(m+'-01T00:00:00Z'))}</option>`));initEvents();render()}).catch(err=>content.innerHTML=`<div class="empty"><b>No se pudo cargar la base</b>${esc(err.message)}</div>`);
